import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, mix, mul, add, float, sin } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'cta-label';

  const width = 2.4;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const brushedMap = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png');
  if (brushedMap) {
    brushedMap.wrapS = THREE.RepeatWrapping;
    brushedMap.wrapT = THREE.RepeatWrapping;
  }

  const inkColor = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surfaceColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);
  const accentColor = vec3(1.0, 0x2a / 255, 0x38 / 255);

  const vUv = uv();

  const gradientMix = add(mul(vUv.x, 0.6), mul(vUv.y, 0.4));
  const baseGradient = mix(surfaceColor, inkColor, gradientMix);

  const grain = mul(sin(mul(vUv.x, 400.0)), sin(mul(vUv.y, 400.0)));
  const grainAmount = mul(grain, 0.015);
  const grainedColor = add(baseGradient, vec3(grainAmount, grainAmount, grainAmount));

  let colorNode;
  if (brushedMap) {
    const metalSample = texture(brushedMap, vUv);
    const blended = mix(grainedColor, mul(grainedColor, metalSample.rgb), 0.35);
    colorNode = blended;
  } else {
    colorNode = grainedColor;
  }

  const edgeBand = float(0.04);
  const isEdge = vUv.y.lessThan(edgeBand);
  const withEdge = mix(colorNode, accentColor, mul(isEdge.select(1.0, 0.0), 0.9));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = vec4(withEdge, 1.0);
  material.transparent = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'cta-label-plane';
  group.add(mesh);

  const textMeshes = [];
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];

  for (const entry of textContent) {
    const textMesh = ctx.fontAtlas.createText({
      text: entry.text,
      font: entry.role === 'headline' ? 'display' : 'text',
      weight: entry.weight || 400,
      sizeEm: entry.role === 'headline' ? 0.34 : 0.13,
      color: '#e8ecf2',
      align: 'center',
      anchor: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
    textMeshes.push(textMesh);
  }

  group.position.set(0, -2.85, 0.26);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (brushedMap && brushedMap.dispose) brushedMap.dispose();
    for (const textMesh of textMeshes) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
      if (textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
        textMesh.userData.cleanup();
      }
    }
  };

  return group;
}
